const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Polygon([[
    [-160, 50],
    [-120, 50],
    [-120, 30],
    [-160, 30],
    [-160, 50]
  ]], null, false);

  const baselineStartDate = '1985-01-01';
  const baselineEndDate = '2012-12-31';
  const targetDateStart = '2019-08-01';
  const targetDateEnd = '2019-08-31';

  // 2. Data Acquisition
  const sstCollection = ee.ImageCollection('NOAA/CDR/OISST/V2.1').select('sst');

  // Baseline: Augusts from 1985-2012
  const baselineCollection = sstCollection
    .filterDate(baselineStartDate, baselineEndDate)
    .filter(ee.Filter.calendarRange(8, 8, 'month'));

  // Target: August 2019
  const targetCollection = sstCollection
    .filterDate(targetDateStart, targetDateEnd);

  // 3. Data Availability Check
  const baselineSize = baselineCollection.size().getInfo();
  const targetSize = targetCollection.size().getInfo();

  if (baselineSize === 0 || targetSize === 0) {
    console.log(`Baseline collection size: ${baselineSize}`);
    console.log(`Target collection size: ${targetSize}`);
    console.log('C1: Empty Collection');
    return;
  }
  console.log(`Baseline image count (Aug 1985-2012): ${baselineSize}`);
  console.log(`Target image count (Aug 2019): ${targetSize}`);

  // 4. Processing and Calculation
  // Create mean composites for each period
  const baselineMeanImage = baselineCollection.mean();
  const targetMeanImage = targetCollection.mean();

  // Reducer arguments
  const reduceArgs = {
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: aoi,
    scale: 30000, // Use a coarse scale for large area ocean analysis
    maxPixels: 1e9
  };

  const baselineStats = baselineMeanImage.reduceRegion(reduceArgs);
  const targetStats = targetMeanImage.reduceRegion(reduceArgs);

  // Fetch results asynchronously
  const baselineResult = await ee.data.computeValue(baselineStats);
  const targetResult = await ee.data.computeValue(targetStats);

  const baselineSST = baselineResult['sst_mean'];
  const baselinePixels = baselineResult['sst_count'];
  const targetSST = targetResult['sst_mean'];
  const targetPixels = targetResult['sst_count'];

  // 5. Validation & Final Answer
  if (baselinePixels === 0 || targetPixels === 0) {
    console.log(`Baseline valid pixels: ${baselinePixels}`);
    console.log(`Target valid pixels: ${targetPixels}`);
    console.log('C2: No Valid Pixels');
    return;
  }

  if (baselineSST === null || targetSST === null || isNaN(baselineSST) || isNaN(targetSST)) {
    console.log(`Baseline SST: ${baselineSST}`);
    console.log(`Target SST: ${targetSST}`);
    console.log('C3: Calculation Failure');
    return;
  }

  // SST is in Kelvin*100, convert to Celsius for interpretability
  const baselineSST_C = (baselineSST / 100) - 273.15;
  const targetSST_C = (targetSST / 100) - 273.15;

  console.log(`Baseline SST (1985-2012 avg): ${baselineSST_C.toFixed(2)} C`);
  console.log(`Target SST (2019 avg): ${targetSST_C.toFixed(2)} C`);
  console.log(`Valid pixel count (Baseline): ${baselinePixels}`);
  console.log(`Valid pixel count (Target): ${targetPixels}`);

  if (targetSST < baselineSST) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log('D');
});
